'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentTheme;
try { currentTheme = localStorage.getItem('praktika-theme'); } catch {}
if (!['dark','light'].includes(currentTheme)) currentTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
function applyTheme(theme) {
 currentTheme=theme; document.documentElement.dataset.theme=theme;
 try { localStorage.setItem('praktika-theme',theme); } catch {}
 document.querySelectorAll('[data-theme-toggle]').forEach(b=>{ b.innerHTML=theme==='dark'?'☀ <span class="theme-text">Ашық режим</span>':'☾ <span class="theme-text">Қараңғы режим</span>'; b.setAttribute('aria-label',theme==='dark'?'Ашық режимге ауысу':'Қараңғы режимге ауысу'); b.setAttribute('aria-pressed',String(theme==='dark')); });
}
document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>applyTheme(currentTheme==='dark'?'light':'dark'));
applyTheme(currentTheme);
const DEMO = !['127.0.0.1','localhost'].includes(location.hostname);
const titles={dashboard:'Шолу',students:'Студенттер',bases:'Практика базалары',contracts:'Келісімшарттар',supervisors:'Жетекшілер',placements:'Практикаға бөлу',diaries:'Күнделік',reports:'Практика есептері',documents:'Жүктелген құжаттар',grades:'Бағалау',analytics:'Статистика',templates:'Құжат үлгілері',assistant:'ЖИ көмекшісі'};
const icons={dashboard:'▦',students:'♧',bases:'▥',contracts:'▤',supervisors:'♙',placements:'⇄',diaries:'▧',reports:'▱',documents:'⇧',grades:'◉',analytics:'▥',templates:'▤',assistant:'✦'};
const defs={
 students:[['name','Аты-жөні'],['group_name','Топ'],['email','Электрондық пошта','email']],
 bases:[['name','Ұйым атауы'],['address','Мекенжайы'],['contact','Байланыс'],['capacity','Орын саны','number']],
 supervisors:[['name','Аты-жөні'],['position','Лауазымы'],['email','Электрондық пошта','email']],
 contracts:[['number','Келісімшарт нөмірі'],['base_id','Практика базасы','bases'],['start_date','Басталуы','date'],['end_date','Аяқталуы','date']],
 placements:[['student_id','Студент','students'],['base_id','Практика базасы','bases'],['supervisor_id','Жетекші','supervisors'],['contract_id','Келісімшарт','contracts'],['kind','Практика түрі'],['start_date','Басталуы','date'],['end_date','Аяқталуы','date']],
 diaries:[['placement_id','Практика','placements'],['date','Күні','date'],['content','Орындалған жұмыс','textarea'],['hours','Сағат','number'],['status','Мәртебе','status'],['feedback','Жетекшінің пікірі','textarea']],
 reports:[['placement_id','Практика','placements'],['title','Есеп тақырыбы'],['content','Есеп мәтіні','textarea'],['status','Мәртебе','status'],['feedback','Жетекшінің пікірі','textarea']],
 grades:[['placement_id','Практика','placements'],['discipline','Тәртіп 10%','number'],['diary','Күнделік 20%','number'],['report','Есеп 40%','number'],['defense','Қорғау 30%','number'],['comment','Пікір','textarea']]
};
let state={user:null,csrf:'',ai_online:false,data:{},documents:[],page:'dashboard',search:'',messages:[]};
let editing=null;
const roleNames={admin:'Практика үйлестірушісі',supervisor:'Практика жетекшісі',student:'Студент'};
async function request(path,method='GET',body){
 const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:body?JSON.stringify(body):undefined});
 const data=await r.json(); if(!r.ok){if(r.status===401&&path!=='login')showLogin();throw Error(data.error||'Сұрау орындалмады.')}return data;
}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500);}
function showLogin(){$('#login').hidden=false;$('#shell').hidden=true;$('#chat-launcher').hidden=true;$('#assistant-window').hidden=true;}
function ref(table,id){return (state.data[table]||[]).find(x=>x.id===Number(id));}
function label(table,id){const r=ref(table,id);if(!r)return '—';if(table==='placements')return label('students',r.student_id)+' · '+label('bases',r.base_id);return r.name||r.number||r.title||'№'+r.id;}
function score(g){return (g.discipline*.1+g.diary*.2+g.report*.4+g.defense*.3).toFixed(1);}
function badge(s){return `<span class="badge ${s==='Түзету қажет'?'bad':s==='Ұсынылды'?'warn':s==='Ұсынылмаған'?'neutral':''}">${esc(s)}</span>`;}
function progress(p){const r=state.data.reports.find(x=>x.placement_id===p.id),g=state.data.grades.find(x=>x.placement_id===p.id);if(g)return 'Бағаланды';if(r)return r.status;return 'Ұсынылмаған';}
function canCreate(entity){return !DEMO&&(state.user.role==='admin'||(state.user.role==='student'&&['diaries','reports'].includes(entity))||(state.user.role==='supervisor'&&entity==='grades'));}
function canEdit(entity,row){if(DEMO)return false;if(state.user.role==='admin')return true;if(state.user.role==='student')return ['diaries','reports'].includes(entity)&&row.status!=='Қабылданды';return ['diaries','reports','grades'].includes(entity);}
function canDelete(entity,row){return canEdit(entity,row)&&(state.user.role!=='supervisor'||entity==='grades');}
async function refresh(){state.data=await request('data');state.documents=await request('documents');render();}
function showApp(){$('#chat-launcher').hidden=false;$('#login').hidden=true;$('#shell').hidden=false;$('#user-name').textContent=state.user.name;$('#user-role').textContent=roleNames[state.user.role];$('#avatar').textContent=state.user.name[0];$('#mode-badge').textContent=DEMO?'Танысу нұсқасы':'SQLite · жергілікті';render();}
function nav(){const keys=Object.keys(titles).filter(k=>k!=='assistant');$('#nav').innerHTML=keys.map(k=>`<button data-page="${k}" class="${state.page===k?'active':''}"><span class="nav-icon">${icons[k]}</span>${titles[k]}${k==='students'?'<span class="count">'+state.data.students.length+'</span>':''}${k==='assistant'?'<span class="count">AI</span>':''}</button>`).join('');}
function heading(subtitle,action=''){return `<div class="breadcrumb">ЖҰМЫС ОРНЫ / ${esc(titles[state.page].toUpperCase())}</div><div class="page-heading"><div><h1>${titles[state.page]}</h1><p>${subtitle}</p></div>${action}</div>`;}
function stat(label,value,note,icon){return `<div class="stat"><div class="stat-top"><span>${label}</span><span>${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
function overview(){const d=state.data,assigned=new Set(d.placements.map(p=>p.student_id)).size,accepted=d.reports.filter(r=>r.status==='Қабылданды').length;
 return heading('Студенттер практикасы туралы мәліметтер.',`<button class="secondary" data-page="analytics">Статистиканы көру ↗</button>`)+`<div class="stats">${stat('Студенттер',d.students.length,'Қолжетімді студенттер','♧')}${stat('Практикаға бөлінді',assigned,'Студент практика базасына бекітілді','⇄')}${stat('Серіктес ұйымдар',d.bases.length,'Практика базалары','▥')}${stat('Қабылданған есептер',accepted,'Жетекші тексерген есептер','✓')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><h3>Практика барысы</h3><button data-page="placements">Барлығын көру →</button></div>${placementTable(d.placements.slice(0,5))}</section><section class="panel"><div class="panel-head"><h3>Тексеру қажет</h3><span class="tag">Бақылау</span></div><div class="tasks"><div class="task"><span class="task-dot">⇄</span><div><b>${d.students.length-assigned} студент бөлінбеген</b><p>Практика базасы мен жетекшіні таңдаңыз.</p></div></div><div class="task"><span class="task-dot">▧</span><div><b>${d.diaries.filter(x=>x.status==='Ұсынылды').length} күнделік тексеруді күтуде</b><p>Жазбаларды қарап, кері байланыс беріңіз.</p></div></div><div class="task"><span class="task-dot">▱</span><div><b>${d.placements.filter(p=>!d.reports.some(r=>r.placement_id===p.id)).length} практикада есеп жоқ</b><p>Есепті мерзімімен бірге бақылаңыз.</p></div></div><div class="task"><span class="task-dot">✦</span><div><b>ЖИ көмекшісі</b><p>Жоспар, күнделік және есеп құрылымы.</p></div></div></div></section></div><section class="panel"><div class="panel-head"><h3>Практика кезеңдері</h3><span class="muted">Бірізді жұмыс үдерісі</span></div><div class="timeline"><span>01 · База және келісімшарт</span><span>02 · Студентті бөлу</span><span>03 · Күнделік жүргізу</span><span>04 · Есепті тексеру</span><span>05 · Қорғау және бағалау</span></div></section>`;
}
function placementTable(rows){return `<div class="table-wrap"><table><thead><tr><th>СТУДЕНТ</th><th>ПРАКТИКА БАЗАСЫ</th><th>МЕРЗІМ</th><th>ЕСЕП МӘРТЕБЕСІ</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(label('students',p.student_id))}</b><small>${esc(ref('students',p.student_id)?.group_name)}</small></td><td>${esc(label('bases',p.base_id))}</td><td>${esc(p.start_date)}<small>${esc(p.end_date)}</small></td><td>${badge(progress(p))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Практика әлі тіркелмеген.</td></tr>'}</tbody></table></div>`;}
function displayCell(key,type,value){if(type==='status')return badge(value);if(defs[type])return esc(label(type,value));if(type==='textarea')return `<div class="content-cell">${esc(value||'—')}</div>`;return esc(value);}
function listPage(){const entity=state.page,fields=defs[entity],rows=state.data[entity].filter(r=>fields.some(([k,l,t])=>String(defs[t]?label(t,r[k]):r[k]).toLocaleLowerCase('kk').includes(state.search.toLocaleLowerCase('kk'))));
 const hiddenFields=['feedback'];const visible=fields.filter(([k])=>!hiddenFields.includes(k));
 return heading('Мәліметтер тізімі',canCreate(entity)?'<button class="primary" id="add-record">+ Жазба қосу</button>':'')+`<div class="toolbar"><input id="search" aria-label="Іздеу" placeholder="Аты, ұйымы немесе мәтіні бойынша іздеу…" value="${esc(state.search)}"><span class="muted">${rows.length} жазба</span>${entity==='placements'?'<button class="secondary" id="export">CSV жүктеу ↓</button>':''}</div><section class="panel"><div class="table-wrap"><table><thead><tr>${visible.map(([,l])=>`<th>${esc(l.toUpperCase())}</th>`).join('')}${entity==='grades'?'<th>ҚОРЫТЫНДЫ</th>':''}<th>ӘРЕКЕТ</th></tr></thead><tbody>${rows.map(r=>`<tr>${visible.map(([k,l,t])=>`<td>${displayCell(k,t,r[k])}${k==='status'&&r.feedback?'<small>'+esc(r.feedback)+'</small>':''}</td>`).join('')}${entity==='grades'?'<td><b>'+score(r)+'</b></td>':''}<td><div class="row-actions">${canEdit(entity,r)?`<button data-edit="${r.id}">${state.user.role==='supervisor'&&['reports','diaries'].includes(entity)?'Тексеру':'Өзгерту'}</button>`:'<span class="muted">Қарау</span>'}${canDelete(entity,r)?`<button class="danger" data-delete="${r.id}">Жою</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${visible.length+2}" class="empty">Жазба табылмады. Іздеу сұрағын өзгертіңіз немесе жаңа жазба қосыңыз.</td></tr>`}</tbody></table></div></section>${entity==='grades'?'<p class="note">Қорытынды = тәртіп × 10% + күнделік × 20% + есеп × 40% + қорғау × 30%. Бұл — оқу жобасының бағалау моделі.</p>':''}${entity==='reports'?'<p class="note">Есеп мәтінін және файл нұсқасын «Жүктелген құжаттар» бөлімінде сақтауға болады.</p>':''}`;
}
function analytics(){const d=state.data,gs=d.grades.map(score).map(Number),average=gs.length?(gs.reduce((a,b)=>a+b,0)/gs.length).toFixed(1):'—';const total=d.placements.length;
 const bars=d.bases.map(b=>{const n=d.placements.filter(p=>p.base_id===b.id).length;return `<div class="bar-row"><span>${esc(b.name)}</span><div class="track"><div class="fill" style="width:${total?n/total*100:0}%"></div></div><b>${n}</b></div>`;}).join('');
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Almaty'});const overdue=d.placements.filter(p=>p.end_date<today&&!d.reports.some(r=>r.placement_id===p.id&&r.status==='Қабылданды'));
 return heading('Практика нәтижелерін талдау және жиынтық ведомость.',`<button class="primary" id="export">CSV жүктеу ↓</button>`)+`<div class="stats">${stat('Практикалар',total,'Барлық қолжетімді тағайындаулар','⇄')}${stat('Бағаланған',gs.length,'Қорытынды балл енгізілді','◉')}${stat('Орташа балл',average,'Тек бағаланған практикалар','↗')}${stat('Мерзімі өткен',overdue.length,'Қабылданған есебі жоқ практика','◷')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><h3>Ұйымдар бойынша бөліну</h3><span class="muted">Тіркелген практикалар саны</span></div><div class="bars">${bars||'<p>Деректер жоқ.</p>'}</div></section><section class="panel"><div class="panel-head"><h3>Есептер жағдайы</h3></div><div class="tasks">${['Қабылданды','Ұсынылды','Түзету қажет','Ұсынылмаған'].map(s=>`<div class="task"><span class="task-dot">▱</span><div><b>${s}</b><p>${d.placements.filter(p=>{let r=d.reports.find(r=>r.placement_id===p.id);return (r?.status||'Ұсынылмаған')===s;}).length} практика</p></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><h3>Жиынтық ведомость</h3><button id="print-report">Басып шығару ↗</button></div>${placementTable(d.placements)}</section><p class="note">Мерзім бақылауы Алматы уақыты бойынша бүгінгі күнмен салыстырылады. CSV файлында қорытынды балл да бар.</p>`;
}
function assistantPage(){if(!state.messages.length)state.messages.push({who:'assistant',text:'Сәлем! Практика жоспарын, күнделік үлгісін немесе есеп құрылымын дайындауға көмектесемін. Қандай сұрағыңыз бар?',label:state.ai_online?'ЖИ қосылған · жауаптарды тексеріңіз':'Офлайн анықтамалық · тілдік модель қосылмаған'});
 return heading('Практика бойынша қазақша кеңес және мәтін дайындауға көмек.')+`<div class="chat-layout"><section class="chat-box"><div class="panel-head"><h3>✦ Практика көмекшісі</h3><span class="tag">${state.ai_online?'ЖИ қосылған':'Офлайн анықтамалық'}</span></div><div class="chat-history" id="chat-history">${messagesHTML()}</div><form class="chat-form" id="chat-form"><input name="message" required maxlength="4000" aria-label="Көмекшіге сұрақ" placeholder="Мысалы, практика есебінің құрылымын ұсын…"><button class="primary" type="submit">Жіберу ↑</button></form></section><section class="panel suggestions"><h3>Неден бастаймыз?</h3>${['Төрт апталық жоспар жаса','Күнделік жазбасының үлгісін бер','Практика есебінің құрылымын ұсын','Баға қалай есептеледі?','Тәуекелдерді талда'].map(t=>`<button data-prompt="${esc(t)}">${t} ↗</button>`).join('')}<p>Көмекшінің мәтіні — жоба үлгісі. Оны нақты орындалған жұмысқа сәйкестендіріңіз.</p><p>ЖИ автоматты түрде баға қоймайды және деректерді өзгертпейді.</p><p>${state.ai_online?'Сұрақ мәтіні және жиынтық сандар сыртқы ЖИ қызметіне жіберіледі. Жеке деректерді енгізбеңіз.':'Тілдік модельді қосу нұсқаулығы жоба архивіндегі README_KK.md файлында бар.'}</p></section></div>`;
}
function messagesHTML(){return state.messages.map(m=>`<div class="message ${m.who==='user'?'user':''}">${m.label?'<small>'+esc(m.label)+'</small>':''}${esc(m.text)}</div>`).join('');}
function templatesPage(){return heading('Студенттерге практика кезінде қолдануға арналған басып шығарылатын бланкілер.', '<button class="primary" id="print-template">Бланкті басып шығару / PDF</button>')+`<div class="toolbar"><label class="template-picker">Бланк түрі<select id="template-kind"><option value="certificate">Практикадан өткені туралы анықтама</option><option value="diary">Студенттің практика күнделігі</option><option value="agreement">Практика өткізу туралы жалпы шарт</option></select></label><span class="muted">Өрістерді толтырып, басып шығару терезесінен PDF сақтаңыз.</span></div><section class="panel document-sheet" id="document-sheet"></section><p class="note">Бұл — толтырылатын оқу үлгілері. Мекеме атауын, деректерді және шарт талаптарын өз ұйымыңыздың бекітілген нұсқасына сәйкестендіріп, қол қоймас бұрын жауапты тұлғалармен келісіңіз.</p>`;}
function templateMarkup(kind){const field=(label,placeholder='')=>`<label>${label}<input placeholder="${placeholder||label+' енгізіңіз'}"></label>`;if(kind==='certificate')return `<div class="doc-center"><b>________________________________________</b><small>(оқу орнының атауы)</small><h2>АНЫҚТАМА</h2><p>Осы анықтама ${field('Студенттің аты-жөні')} ${field('Тобы')} тобының студенті екенін және ${field('Практика базасының атауы')} ұйымында ${field('Практика түрі')} практикасын ${field('Басталу күні','күні/айы/жылы')} бастап ${field('Аяқталу күні','күні/айы/жылы')} дейін өткенін растау үшін берілді.</p><p>Анықтама талап етілген жерге ұсыну үшін берілді.</p><div class="doc-sign">${field('Берілген күні','күні/айы/жылы')} ${field('Жауапты тұлға, лауазымы')} <span>____________________ (қолы)</span><span>М.О.</span></div></div>`;if(kind==='diary')return `<div class="doc-center"><h2>КӘСІБИ ПРАКТИКА КҮНДЕЛІГІ</h2></div><div class="doc-fields">${field('Студенттің аты-жөні')}${field('Тобы')}${field('Мамандығы')}${field('Практика базасы')}${field('Ұйымдағы жетекші')}${field('Оқу орнындағы жетекші')}${field('Практика мерзімі','басталу – аяқталу')}</div><p>Күн сайын орындалған жұмысты, нәтижені және жұмсалған сағатты жазыңыз.</p><table class="diary-template"><thead><tr><th>Күні</th><th>Орындалған жұмыс және нәтиже</th><th>Сағат</th><th>Жетекші қолы</th></tr></thead><tbody>${Array.from({length:12},()=>'<tr><td></td><td></td><td></td><td></td></tr>').join('')}</tbody></table><div class="doc-sign"><span>Студенттің қолы: __________________</span><span>Ұйым жетекшісінің пікірі: __________________________________________</span><span>Жетекшінің қолы: __________________  Күні: ______________</span></div>`;return `<div class="doc-center"><b>________________________________________</b><small>(оқу орнының атауы)</small><h2>КӘСІБИ ПРАКТИКАНЫ ҰЙЫМДАСТЫРУ ЖӘНЕ ӨТКІЗУ ТУРАЛЫ ШАРТ</h2><p>№ ${field('Шарт нөмірі')} &nbsp;&nbsp; ${field('Қала')} қ. &nbsp;&nbsp; «___» __________ 20___ ж.</p></div><p>Бұдан әрі «Оқу орны» деп аталатын ${field('Оқу орнының толық атауы')}, атынан ${field('Оқу орны атынан қол қоюшының аты-жөні мен лауазымы')} негізінде әрекет ететін, бір тараптан, және бұдан әрі «Практика базасы» деп аталатын ${field('Ұйымның толық атауы')}, атынан ${field('Ұйым атынан қол қоюшының аты-жөні мен лауазымы')} негізінде әрекет ететін, екінші тараптан, төмендегілер туралы осы шартты жасасты.</p><h3>1. Шарттың мәні</h3><p>1.1. Практика базасы студенттердің кәсіби практикадан өтуіне жағдай жасайды. Оқу орны студенттерді практикаға жібереді және оқу-әдістемелік жетекшілікті қамтамасыз етеді.</p><h3>2. Тараптардың міндеттері</h3><p>2.1. Оқу орны студенттер тізімін, практика мерзімін және бағдарламасын практика басталғанға дейін ұсынады; жетекші тағайындайды.</p><p>2.2. Практика базасы студенттерге жұмыс орнын және қауіпсіздік бойынша нұсқама береді; ұйым жетекшісін тағайындайды; практика нәтижесіне пікір ұсынады.</p><p>2.3. Студент ішкі тәртіпті, еңбекті қорғау және қауіпсіздік талаптарын сақтап, күнделік пен қорытынды есепті жүргізеді.</p><h3>3. Практиканы өткізу тәртібі</h3><p>Практика мерзімі: ${field('Басталу күні','күні/айы/жылы')} – ${field('Аяқталу күні','күні/айы/жылы')}. Практика түрі/бағдарламасы: ${field('Практика түрі немесе бағдарлама')}.</p><h3>4. Қорытынды ережелер</h3><p>Шарт тараптардың келісімімен өзгертіледі. Даулар келіссөздер арқылы шешіледі. Шарт екі данада жасалып, тараптар қол қойған күннен бастап күшіне енеді және практика аяқталғанға дейін қолданылады.</p><h3>5. Тараптардың деректемелері мен қолдары</h3><div class="doc-fields"><div><b>ОҚУ ОРНЫ</b>${field('Мекенжайы')}${field('БСН')}${field('Банк деректемелері / байланыс')}${field('Басшының аты-жөні')}<span>Қолы: __________________ М.О.</span></div><div><b>ПРАКТИКА БАЗАСЫ</b>${field('Мекенжайы')}${field('БСН')}${field('Банк деректемелері / байланыс')}${field('Басшының аты-жөні')}<span>Қолы: __________________ М.О.</span></div></div>`;}
function renderTemplate(){const sheet=$('#document-sheet');if(sheet)sheet.innerHTML=templateMarkup($('#template-kind').value);}
function documentsPage(){
 const placements=state.data.placements||[],docs=state.documents||[];
 const options=placements.map(p=>`<option value="${p.id}">${esc(label('placements',p.id))} · ${esc(p.start_date)} — ${esc(p.end_date)}</option>`).join('');
 const rows=docs.map(d=>`<tr><td>${esc(({diary:'Күнделік',certificate:'Анықтама',contract:'Жалпы шарт',report:'Есеп'})[d.document_type]||d.document_type)}</td><td>${esc(d.original_name)}</td><td>${esc(label('placements',d.placement_id))}</td><td>${esc(d.uploaded_by||'—')}</td><td>${esc(d.created_at)}<small>${(d.file_size/1024).toFixed(1)} КБ</small></td><td>${badge(d.status)}</td><td><div class="row-actions"><button data-download-document="${d.id}">Жүктеп алу ↓</button>${(state.user.role==='admin'||(state.user.role==='student'&&d.user_id===state.user.id&&d.status==='Ұсынылды'))?`<button class="danger" data-delete-document="${d.id}">Жою</button>`:''}</div></td></tr>`).join('');
 return heading('Студент өз практикасына күнделік, анықтама, жалпы шарт және қорытынды есеп файлын жүктейді. Жетекші құжаттарды қарап, кері байланыс береді.')+`<section class="panel"><div class="panel-head"><h3>Практика құжатын жіберу</h3><span class="tag">PDF, Word, Excel, JPG, PNG · 10 МБ дейін</span></div>${placements.length?`<form id="upload-form" class="form-grid"><label>Практика<select name="placement_id" required>${options}</select></label><label>Құжат түрі<select name="document_type" required><option value="diary">Күнделік файлы</option><option value="certificate">Практика анықтамасы</option><option value="contract">Жалпы шарт</option><option value="report">Практика есебі</option></select></label><label class="file-picker">Файлды таңдаңыз<input name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png" required></label><div class="dialog-actions"><button class="primary" type="submit">Файлды жүктеу ↑</button></div><div id="upload-error" role="alert"></div></form>`:'<p class="empty">Сізге практика тағайындалмаған. Үйлестірушіге хабарласыңыз.</p>'}</section><section class="panel"><div class="panel-head"><h3>Жүктелген құжаттар</h3><span class="muted">${docs.length} файл</span></div><div class="table-wrap"><table><thead><tr><th>ТҮРІ</th><th>ФАЙЛ</th><th>ПРАКТИКА</th><th>ЖҮКТЕГЕН</th><th>УАҚЫТЫ / ӨЛШЕМІ</th><th>МӘРТЕБЕСІ</th><th>ӘРЕКЕТ</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="empty">Әзірше файл жүктелмеген.</td></tr>'}</tbody></table></div></section><p class="note">Құжаттар тек өз практикасына тағайындалған студентке, сол практиканың жетекшісіне және үйлестірушіге көрінеді. Оқытушы қабылдағаннан кейін студент жүктеген файлды жоя алмайды.</p>`;
}
async function uploadDocument(e){e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),error=$('#upload-error');error.textContent='';const file=form.elements.file.files[0];if(!file)return; if(file.size>10*1024*1024){error.textContent='Файл 10 МБ-тан аспауы керек.';return;}button.disabled=true;try{const data=new FormData(form);const response=await fetch('/api/documents',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:data});const result=await response.json();if(!response.ok)throw Error(result.error||'Файлды жүктеу сәтсіз аяқталды.');await refresh();toast('Құжат сәтті жүктелді.');}catch(err){error.textContent=err.message;}finally{button.disabled=false;}}
async function downloadDocument(id){try{const r=await fetch(`/api/documents/${id}/download`,{headers:{'X-CSRF-Token':state.csrf}});if(!r.ok){const x=await r.json();throw Error(x.error||'Файлды алу мүмкін болмады.');}const blob=await r.blob();const dispo=r.headers.get('Content-Disposition')||'';const encoded=dispo.match(/filename\*=UTF-8''([^;]+)/i);const filename=encoded?decodeURIComponent(encoded[1]):'praktika-document';const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){toast(e.message);}}
async function deleteDocument(id){if(!confirm('Осы файлды жою керек пе?'))return;try{await request(`documents/${id}`,'DELETE');await refresh();toast('Файл жойылды.');}catch(e){toast(e.message);}}
function render(){nav();let content=state.page==='dashboard'?overview():state.page==='analytics'?analytics():state.page==='templates'?templatesPage():state.page==='documents'?documentsPage():state.page==='assistant'?assistantPage():listPage();$('#main').innerHTML=(DEMO?'<div class="demo-banner">Танысу нұсқасы: оқу деректерін қарай аласыз. Деректерді сақтау, рөлдер және нақты ЖИ жоба архивіндегі Python серверінде жұмыс істейді.</div>':'')+content;bindMain();}
function switchPage(page){state.page=page;state.search='';render();window.scrollTo(0,0);}
function bindMain(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));$('#add-record')?.addEventListener('click',()=>openEditor());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(Number(b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteRecord(Number(b.dataset.delete)));$('#search')?.addEventListener('input',e=>{const start=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start);});$('#upload-form')?.addEventListener('submit',uploadDocument);document.querySelectorAll('[data-download-document]').forEach(b=>b.onclick=()=>downloadDocument(Number(b.dataset.downloadDocument)));document.querySelectorAll('[data-delete-document]').forEach(b=>b.onclick=()=>deleteDocument(Number(b.dataset.deleteDocument)));$('#export')?.addEventListener('click',exportCSV);$('#print-report')?.addEventListener('click',()=>window.print());$('#template-kind')?.addEventListener('change',renderTemplate);$('#print-template')?.addEventListener('click',()=>window.print());renderTemplate();$('#chat-form')?.addEventListener('submit',chatSubmit);document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('#chat-form input').value=b.dataset.prompt;$('#chat-form input').focus();});}
function openEditor(id){const entity=state.page,row=id?ref(entity,id):{};editing={entity,id};$('#editor-title').textContent=id?'Жазбаны өзгерту':'Жаңа жазба';$('#form-error').textContent='';$('#form-fields').innerHTML=defs[entity].map(([key,name,type])=>{
 const student=state.user.role==='student',supervisor=state.user.role==='supervisor';if(student&&['status','feedback'].includes(key))return '';const disabled=supervisor&&['diaries','reports'].includes(entity)&&!['status','feedback'].includes(key);
 const value=row[key]??(key==='status'?'Ұсынылды':key==='kind'?'Өндірістік практика':'');let input='';const attrs=`name="${key}" ${disabled?'disabled':''} ${['feedback','comment'].includes(key)?'':'required'}`;
 if(defs[type])input=`<select ${attrs}><option value="">Таңдаңыз</option>${state.data[type].map(r=>`<option value="${r.id}" ${r.id===Number(value)?'selected':''}>${esc(label(type,r.id))}</option>`).join('')}</select>`;
 else if(type==='status')input=`<select ${attrs}>${['Ұсынылды','Қабылданды','Түзету қажет'].map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select>`;
 else if(type==='textarea')input=`<textarea ${attrs} maxlength="20000">${esc(value)}</textarea>`;
 else input=`<input ${attrs} type="${type||'text'}" value="${esc(value)}" ${type==='number'?`step="1" min="${['hours','capacity'].includes(key)?1:0}" max="${key==='hours'?12:key==='capacity'?10000:100}"`:''}>`;
 return `<label class="${type==='textarea'?'wide':''}">${name}${input}</label>`;}).join('');$('#editor').showModal();}
async function saveRecord(e){e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;const {entity,id}=editing;const row=id?ref(entity,id):{};const data={...row,...Object.fromEntries(new FormData(e.target))};if(state.user.role==='student'&&['diaries','reports'].includes(entity)){data.status='Ұсынылды';data.feedback='';}try{await request(entity+(id?'/'+id:''),id?'PUT':'POST',data);$('#editor').close();await refresh();toast('Жазба сақталды.');}catch(err){$('#form-error').textContent=err.message;}finally{button.disabled=false;}}
async function deleteRecord(id){if(!confirm('Жазбаны жою керек пе? Байланысқан деректер болса, жою орындалмайды.'))return;try{await request(state.page+'/'+id,'DELETE');await refresh();toast('Жазба жойылды.');}catch(err){toast(err.message);}}
async function exportCSV(){if(!DEMO){location.href='/api/export';return;}const rows=[['Студент','База','Басталуы','Аяқталуы','Есеп мәртебесі'],...state.data.placements.map(p=>[label('students',p.student_id),label('bases',p.base_id),p.start_date,p.end_date,progress(p)])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='praktika-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function demoAnswer(q){q=q.toLowerCase();if(q.includes('күнделік'))return 'Күнделік үлгісі\nКүні: [нақты күн]\nОрындалған жұмыс: [тапсырма]\nҚолданылған құралдар: [технология]\nНәтиже: [нақты нәтиже]\nҮйренгенім: [дағды]\nЖұмыс уақыты: [сағат].\n\nҮлгіні өзіңіз орындаған жұмыспен толықтырыңыз.';if(q.includes('баға'))return 'Қорытынды балл = тәртіп × 10% + күнделік × 20% + есеп × 40% + қорғау × 30%. Әр критерий 0–100 аралығында. Бұл оқу жобасының моделі.';if(q.includes('жоспар'))return '1-апта: ұйыммен және қауіпсіздік талаптарымен танысу.\n2-апта: тапсырманы талдау және жобалау.\n3-апта: іске асыру және тестілеу.\n4-апта: есепті дайындау және қорғау.\n\nНақты мерзім мен тапсырманы жетекшімен келісіңіз.';if(q.includes('тәуекел'))return 'Есебі жоқ практикаларды және тексеруді күтіп тұрған күнделіктерді бақылаңыз. Мерзімдерді «Практикаға бөлу» бөлімінен қараңыз. Толық деректермен жұмыс істеу үшін Python нұсқасын іске қосыңыз.';return 'Есеп құрылымы\n1. Титул парағы.\n2. Кіріспе және мақсат.\n3. Ұйым сипаттамасы.\n4. Орындалған жұмыс пен нәтижелер.\n5. Қолданылған технологиялар.\n6. Қорытынды.\n7. Әдебиеттер және қосымшалар.\n\nБұл — дайын үлгі. ЖОО нұсқаулығына және өз жұмысыңызға сәйкестендіріңіз.';}
async function chatSubmit(e){e.preventDefault();const input=e.target.elements.message,text=input.value.trim();if(!text)return;input.value='';const button=e.target.querySelector('button');button.disabled=true;state.messages.push({who:'user',text});$('#chat-history').innerHTML=messagesHTML();$('#chat-history').scrollTop=1e6;try{const r=DEMO?{answer:demoAnswer(text),label:'Танысу нұсқасы · дайын анықтамалық'}:await request('assistant','POST',{message:text});state.messages.push({who:'assistant',text:r.answer,label:r.label});}catch(err){state.messages.push({who:'assistant',text:err.message,label:'Сұрау қатесі'});}finally{if($('#chat-history')){$('#chat-history').innerHTML=messagesHTML();$('#chat-history').scrollTop=1e6;}button.disabled=false;}}
$('#edit-form').addEventListener('submit',saveRecord);$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();$('#logout').onclick=async()=>{if(DEMO){showLogin();return;}try{await request('logout','POST');state.messages=[];showLogin();}catch(e){toast(e.message);}};
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{if(DEMO){await startDemo();return;}await request('login','POST',Object.fromEntries(new FormData(e.target)));await startLocal();}catch(err){$('#login-error').textContent=err.message;}finally{button.disabled=false;}});
async function startLocal(){const me=await request('me');Object.assign(state,me);state.data=await request('data');state.documents=await request('documents');showApp();}
async function startDemo(){state.user={name:'Практика үйлестірушісі',role:'admin'};state.data=await (await fetch('seed.json')).json();state.ai_online=false;state.documents=[];showApp();}
if(DEMO){startDemo().catch(e=>{$('#login-error').textContent=e.message;});}else{startLocal().catch(()=>showLogin());}

function openFloatingChat(){
 const windowEl=$('#assistant-window');
 if(!windowEl.hidden){windowEl.hidden=true;return;}
 if(!state.messages.length)state.messages.push({who:'assistant',text:'Сәлем! Практика бойынша қандай сұрағыңыз бар?',label:state.ai_online?'ЖИ көмекшісі':'Офлайн анықтамалық'});
 windowEl.innerHTML=`<div class="floating-chat-head"><div><b>ЖИ көмекшісі</b><small>${state.ai_online?'ЖИ қосылған':'Офлайн анықтамалық'}</small></div><button id="close-chat" aria-label="Чатты жабу">×</button></div><div class="chat-history" id="chat-history">${messagesHTML()}</div><form class="chat-form" id="chat-form"><input name="message" required maxlength="4000" aria-label="Көмекшіге сұрақ" placeholder="Сұрағыңызды жазыңыз"><button class="primary" type="submit" aria-label="Жіберу">↑</button></form><p class="chat-disclaimer">Жауапты өз жұмысыңызға сәйкестендіріп тексеріңіз.</p>`;
 windowEl.hidden=false;$('#close-chat').onclick=()=>windowEl.hidden=true;$('#chat-form').addEventListener('submit',chatSubmit);$('#chat-form input').focus();
}
$('#chat-launcher').onclick=openFloatingChat;
